import Foundation

/// Primera classificació dels dibuixos, feta mirant-los un per un (nom del fitxer → "Categoria|instrument").
/// Només és un suggeriment: a la revisió es pot canviar, i el que es desa a la fulla mana.
enum TshirtsPreclass {
    static let map: [String: (categoria: String, instrument: String)] = {
        guard let data = json.data(using: .utf8),
              let raw = try? JSONDecoder().decode([String: String].self, from: data) else { return [:] }
        var out: [String: (categoria: String, instrument: String)] = [:]
        for (name, value) in raw {
            let parts = value.split(separator: "|", omittingEmptySubsequences: false).map(String.init)
            out[key(name)] = (parts.first ?? "", parts.count > 1 ? parts[1] : "")
        }
        return out
    }()

    /// Mateix nom encara que vingui escrit amb accents compostos o descompostos.
    static func key(_ name: String) -> String { name.precomposedStringWithCanonicalMapping.lowercased() }

